mapper.select:
SELECT ID, AMOUNT, STORE_ID, CATEGORY_ID, PAYER_ID, PAYMENT_DATE, SPLIT_FLG, REMARKS, REGISTER_DATE, USER_ID
FROM TBL_EXPENSE

    USER_ID = #{userId}

SELECT ID, AMOUNT, STORE_ID, CATEGORY_ID, PAYER_ID, PAYMENT_DATE, SPLIT_FLG, REMARKS, REGISTER_DATE, USER_ID
FROM TBL_EXPENSE

    ID = #{id}

SELECT ID, AMOUNT, STORE_ID, CATEGORY_ID, PAYER_ID, PAYMENT_DATE, SPLIT_FLG, REMARKS, REGISTER_DATE, USER_ID
FROM TBL_EXPENSE



    PAYMENT_DATE BETWEEN #{startDate} AND #{endDate}



    AND STORE_ID = #{storeId}



    AND CATEGORY_ID = #{categoryId}



    AND PAYER_ID = #{payerId}



    AND REMARKS LIKE CONCAT('%', #{remarks}, '%')



    AND USER_ID = #{userId}


ORDER BY PAYMENT_DATE DESC, ID DESC
